import {
  defineComponent,
  h,
  inject,
  onMounted,
  provide,
  ref,
  shallowRef,
  toRef,
  watch,
  type Component,
  type InjectionKey,
  type PropType,
  type Ref,
} from 'vue';
import {
  AnimatePresence,
  cancelFrame,
  frame,
  motion,
  useMotionValue,
  useSpring,
  type MotionValue,
  type SpringOptions,
  type Transition,
} from 'motion-v';

import {
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from '../../utils/motion';
import { Slot } from '../slot';

const OPACITY_TRANSITION: Transition = {
  duration: 0.3,
  ease: [0.25, 0.1, 0.35, 1],
};
const ENTER_TRANSITION: Transition = {
  scale: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  opacity: OPACITY_TRANSITION,
};
const EXIT_TRANSITION: Transition = {
  scale: {
    type: 'spring',
    stiffness: 550,
    damping: 2 * Math.sqrt(550),
    restSpeed: 10,
  },
  opacity: OPACITY_TRANSITION,
};
const FOLLOW_SPRING: SpringOptions = { stiffness: 500, damping: 50, bounce: 0 };

type CursorContextType = {
  cursorX: MotionValue<number>;
  cursorY: MotionValue<number>;
  active: Ref<boolean>;
  global: () => boolean;
  container: Ref<HTMLElement | null>;
  cursor: Ref<HTMLElement | null>;
};

const CursorKey: InjectionKey<CursorContextType> = Symbol('AnimateUICursor');

function useCursor() {
  const context = inject(CursorKey, null);
  if (!context)
    throw new Error('useCursor must be used within a CursorProvider');
  return context;
}

const elementOf = (node: unknown) => {
  const element = (node as { $el?: unknown } | null)?.$el ?? node;
  return element instanceof HTMLElement ? element : null;
};

type CursorProviderProps = {
  global?: boolean;
};

/** Follows the pointer, over its container's parent or the whole page. */
const CursorProvider = defineComponent({
  name: 'CursorProvider',
  props: {
    global: Boolean,
  },
  setup(props, { slots }) {
    const cursorX = useMotionValue(0);
    const cursorY = useMotionValue(0);
    const active = ref(false);
    const container = shallowRef<HTMLElement | null>(null);
    const cursor = shallowRef<HTMLElement | null>(null);
    const setActive = (next: boolean) => {
      if (active.value !== next) active.value = next;
    };

    onMounted(() => {
      const id = '__cursor_none_style__';
      if (document.getElementById(id)) return;
      const style = document.createElement('style');
      style.id = id;
      style.textContent = `
      .animate-ui-cursor-none, .animate-ui-cursor-none * { cursor: none !important; }
    `;
      document.head.appendChild(style);
    });

    watch(
      () => [props.global, container.value] as const,
      ([global, element], _, onCleanup) => {
        if (global) {
          const handlePointerMove = (e: PointerEvent) => {
            if (e.pointerType === 'touch') return;
            cursorX.set(e.clientX);
            cursorY.set(e.clientY);
            setActive(true);
          };
          const handlePointerOut = (e: PointerEvent | MouseEvent) => {
            if (e instanceof PointerEvent && e.relatedTarget === null)
              setActive(false);
          };
          const handleVisibilityChange = () => {
            if (document.visibilityState === 'hidden') setActive(false);
          };
          window.addEventListener('pointermove', handlePointerMove, {
            passive: true,
          });
          window.addEventListener('pointerout', handlePointerOut, {
            passive: true,
          });
          window.addEventListener('mouseout', handlePointerOut, {
            passive: true,
          });
          document.addEventListener('visibilitychange', handleVisibilityChange);
          onCleanup(() => {
            window.removeEventListener('pointermove', handlePointerMove);
            window.removeEventListener('pointerout', handlePointerOut);
            window.removeEventListener('mouseout', handlePointerOut);
            document.removeEventListener(
              'visibilitychange',
              handleVisibilityChange,
            );
          });
          return;
        }

        const parent = element?.parentElement;
        if (!parent) return;
        if (getComputedStyle(parent).position === 'static')
          parent.style.position = 'relative';

        const handlePointerMove = (e: PointerEvent) => {
          if (e.pointerType === 'touch') return;
          const rect = parent.getBoundingClientRect();
          cursorX.set(e.clientX - rect.left);
          cursorY.set(e.clientY - rect.top);
          setActive(true);
        };
        const handlePointerOut = (e: PointerEvent | MouseEvent) => {
          if (
            e.relatedTarget === null ||
            !parent.contains(e.relatedTarget as Node)
          )
            setActive(false);
        };
        parent.addEventListener('pointermove', handlePointerMove, {
          passive: true,
        });
        parent.addEventListener('pointerout', handlePointerOut, {
          passive: true,
        });
        parent.addEventListener('mouseout', handlePointerOut, {
          passive: true,
        });
        onCleanup(() => {
          parent.removeEventListener('pointermove', handlePointerMove);
          parent.removeEventListener('pointerout', handlePointerOut);
          parent.removeEventListener('mouseout', handlePointerOut);
        });
      },
      { immediate: true, flush: 'post' },
    );

    provide(CursorKey, {
      cursorX,
      cursorY,
      active,
      global: () => props.global,
      container,
      cursor,
    });

    return () => h(ReducedMotionConfig, null, slots);
  },
});

type CursorContainerProps = {
  asChild?: boolean;
};

/** Marks the area: the cursor follows the pointer over its parent. */
const CursorContainer = defineComponent({
  name: 'CursorContainer',
  inheritAttrs: false,
  props: {
    asChild: Boolean,
  },
  setup(props, { attrs, slots }) {
    const { container, global, active } = useCursor();
    return () =>
      h(
        (props.asChild ? Slot : motion.div) as Component,
        {
          'data-slot': 'cursor-container',
          'data-global': global(),
          'data-active': active.value,
          ...attrs,
          ref: (node: unknown) => {
            container.value = elementOf(node);
          },
        },
        slots,
      );
  },
});

type CursorProps = {
  asChild?: boolean;
  transition?: Transition;
};

/** The cursor drawn in place of the system one. */
const Cursor = defineComponent({
  name: 'Cursor',
  inheritAttrs: false,
  props: {
    asChild: Boolean,
    transition: Object as PropType<Transition>,
  },
  setup(props, { attrs, slots }) {
    const { cursorX, cursorY, active, container, cursor, global } = useCursor();
    const enterTransition = useTempoTransition(() => ENTER_TRANSITION);
    const exitTransition = useTempoTransition(() => EXIT_TRANSITION);

    watch(
      () => [active.value, global(), container.value] as const,
      ([isActive, isGlobal, element], _, onCleanup) => {
        const target = isGlobal
          ? document.documentElement
          : element?.parentElement;
        if (!target) return;
        target.classList.toggle('animate-ui-cursor-none', isActive);
        onCleanup(() => target.classList.remove('animate-ui-cursor-none'));
      },
      { immediate: true, flush: 'post' },
    );

    return () =>
      h(AnimatePresence as Component, null, () =>
        active.value
          ? h(
              (props.asChild ? Slot : motion.div) as Component,
              {
                'data-slot': 'cursor',
                'data-global': global(),
                'data-active': active.value,
                initial: { scale: 0, opacity: 0 },
                animate: { scale: 1, opacity: 1 },
                exit: {
                  scale: 0,
                  opacity: 0,
                  ...(props.transition
                    ? {}
                    : { transition: exitTransition.value }),
                },
                transition: props.transition ?? enterTransition.value,
                ...attrs,
                ref: (node: unknown) => {
                  cursor.value = elementOf(node);
                },
                style: [
                  {
                    pointerEvents: 'none',
                    zIndex: 9999,
                    position: global() ? 'fixed' : 'absolute',
                    top: 0,
                    left: 0,
                    x: cursorX,
                    y: cursorY,
                  },
                  attrs.style,
                ],
              },
              slots,
            )
          : null,
      );
  },
});

type CursorFollowSide = 'top' | 'right' | 'bottom' | 'left';
type CursorFollowAlign = 'start' | 'center' | 'end';

type CursorFollowProps = {
  asChild?: boolean;
  side?: CursorFollowSide;
  sideOffset?: number;
  align?: CursorFollowAlign;
  alignOffset?: number;
  transition?: SpringOptions;
};

/** An element that trails the cursor, on a spring. */
const CursorFollow = defineComponent({
  name: 'CursorFollow',
  inheritAttrs: false,
  props: {
    asChild: Boolean,
    side: { type: String as PropType<CursorFollowSide>, default: 'bottom' },
    sideOffset: { type: Number, default: 0 },
    align: { type: String as PropType<CursorFollowAlign>, default: 'end' },
    alignOffset: { type: Number, default: 0 },
    transition: Object as PropType<SpringOptions>,
  },
  setup(props, { attrs, slots }) {
    const defaultTransition = useTempoTransition(() => FOLLOW_SPRING);
    const enterTransition = useTempoTransition(() => ENTER_TRANSITION);
    const exitTransition = useTempoTransition(() => EXIT_TRANSITION);
    const { cursorX, cursorY, active, cursor, global } = useCursor();
    const reduce = useShouldReduceMotion();
    const follow = shallowRef<HTMLElement | null>(null);

    const x = useMotionValue(0);
    const y = useMotionValue(0);
    const spring = toRef(
      () => props.transition ?? (defaultTransition.value as SpringOptions),
    );
    const springX = useSpring(x, spring);
    const springY = useSpring(y, spring);

    const calculateOffset = () => {
      const rect = follow.value?.getBoundingClientRect();
      const width = rect?.width ?? 0;
      const height = rect?.height ?? 0;
      const { side, align, sideOffset, alignOffset } = props;
      let offsetX = 0;
      let offsetY = 0;
      const along = (size: number) =>
        align === 'start'
          ? size + alignOffset
          : align === 'center'
            ? size / 2
            : -alignOffset;
      switch (side) {
        case 'top':
          offsetY = height + sideOffset;
          offsetX = along(width);
          break;
        case 'bottom':
          offsetY = -sideOffset;
          offsetX = along(width);
          break;
        case 'left':
          offsetX = width + sideOffset;
          offsetY = along(height);
          break;
        case 'right':
          offsetX = -sideOffset;
          offsetY = along(height);
          break;
      }
      return { x: offsetX, y: offsetY };
    };

    const update = () => {
      const offset = calculateOffset();
      const cursorRect = cursor.value?.getBoundingClientRect();
      const cursorWidth = cursorRect?.width ?? 20;
      const cursorHeight = cursorRect?.height ?? 20;
      x.set(cursorX.get() - offset.x + cursorWidth / 2);
      y.set(cursorY.get() - offset.y + cursorHeight / 2);
    };

    watch(
      () => [props.side, props.align, props.sideOffset, props.alignOffset],
      update,
      { immediate: true },
    );

    watch(
      active,
      (isActive, _, onCleanup) => {
        if (!isActive) return;
        frame.postRender(update);
        const unsubscribeX = cursorX.on('change', update);
        const unsubscribeY = cursorY.on('change', update);
        onCleanup(() => {
          cancelFrame(update);
          unsubscribeX();
          unsubscribeY();
        });
      },
      { immediate: true },
    );

    return () =>
      h(AnimatePresence as Component, null, () =>
        active.value
          ? h(
              (props.asChild ? Slot : motion.div) as Component,
              {
                'data-slot': 'cursor-follow',
                'data-global': global(),
                'data-active': active.value,
                initial: { scale: 0, opacity: 0 },
                animate: { scale: 1, opacity: 1 },
                exit: {
                  scale: 0,
                  opacity: 0,
                  transition: exitTransition.value,
                },
                transition: enterTransition.value,
                ...attrs,
                ref: (node: unknown) => {
                  follow.value = elementOf(node);
                },
                style: [
                  {
                    pointerEvents: 'none',
                    zIndex: 9998,
                    position: global() ? 'fixed' : 'absolute',
                    top: 0,
                    left: 0,
                    x: reduce.value ? x : springX,
                    y: reduce.value ? y : springY,
                  },
                  attrs.style,
                ],
              },
              slots,
            )
          : null,
      );
  },
});

export {
  CursorProvider,
  Cursor,
  CursorContainer,
  CursorFollow,
  useCursor,
  type CursorProviderProps,
  type CursorProps,
  type CursorContainerProps,
  type CursorFollowProps,
  type CursorFollowAlign,
  type CursorFollowSide,
  type CursorContextType,
};

import {
  computed,
  defineComponent,
  Fragment,
  getCurrentInstance,
  h,
  inject,
  onBeforeUnmount,
  onMounted,
  ref,
  type ComputedRef,
  type InjectionKey,
  type Ref,
} from 'vue';
import {
  createGeneratorEasing,
  generateLinearEasing,
  MotionConfig,
  spring as springGenerator,
  useMotionConfig,
  type Transition,
} from 'motion-v';

const ease = {
  out: [0.23, 1, 0.32, 1],
  soft: [0.215, 0.61, 0.355, 1],
  draw: [0, 0, 0.58, 1],
  inOut: [0.77, 0, 0.175, 1],
  away: [0.33, 0.17, 0.67, 0.5],
  in: [0.4, 0, 1, 1],
  drawer: [0.34, 1.2, 0.64, 1],
  arrive: [0.11, 0, 0.5, 0],
  color: [0.25, 0.1, 0.25, 1],
  leave: [0, 0, 0.58, 1],
  enter: [0.25, 0.1, 0.35, 1],
  resize: [0.4, 0, 0.1, 1],
  fill: [0.4, 0, 0.2, 1],
} as const;

const spring = {
  press: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  pop: { type: 'spring', stiffness: 400, damping: 29 },
  tooltip: { type: 'spring', stiffness: 400, damping: 31 },
  dialog: { type: 'spring', stiffness: 150, damping: 25 },
  toast: { type: 'spring', stiffness: 280, damping: 24 },
  selection: { type: 'spring', stiffness: 300, damping: 30 },
  highlight: { type: 'spring', stiffness: 500, damping: 40 },
  reflow: { type: 'spring', stiffness: 500, damping: 40 },
  handoff: { type: 'spring', stiffness: 450, damping: 43 },
  morph: { type: 'spring', stiffness: 660, damping: 52 },
  height: {
    type: 'spring',
    stiffness: 300,
    damping: 30,
    bounce: 0,
    restDelta: 0.01,
  },
  slide: { type: 'spring', stiffness: 300, damping: 35, restDelta: 0.01 },
  thumb: { type: 'spring', stiffness: 300, damping: 25 },
  slider: { type: 'spring', stiffness: 400, damping: 32 },
  bounce: { type: 'spring', stiffness: 200, damping: 16 },
  glyph: { type: 'spring', stiffness: 500, damping: 45 },
  checkPop: { type: 'spring', stiffness: 500, damping: 24 },
  entrance: { type: 'spring', stiffness: 200, damping: 20 },
  progress: {
    type: 'spring',
    stiffness: 300,
    damping: 35,
    restDelta: 0.01,
    restSpeed: 0.1,
  },
  number: { type: 'spring', stiffness: 90, damping: 50 },
} as const satisfies Record<string, Transition>;

const transition = {
  menu: { duration: 0.22, ease: ease.soft },
  overlay: { duration: 0.4, ease: ease.soft },
  dialogFade: { duration: 0.4, ease: ease.soft },
  fade: { duration: 0.2, ease: ease.out },
  color: { duration: 0.2, ease: ease.color },
  reveal: { duration: 0.3, ease: ease.out },
  disclosure: { duration: 0.35, ease: ease.soft },
  panelOut: { duration: 0.15, ease: ease.leave },
  panelIn: { duration: 0.3, ease: ease.enter },
  tooltipIn: { duration: 0.34, ease: ease.enter },
  tooltipOut: { duration: 0.13, ease: ease.leave },
  panelHeight: { duration: 0.45, ease: ease.resize },
  check: { duration: 0.3, delay: 0.2, ease: ease.draw },
  uncheck: { duration: 0.3, ease: ease.draw },
  fill: { duration: 0.3, ease: ease.fill },
  popOut: { duration: 0.15, ease: ease.out },
  swap: { duration: 0.15, ease: ease.out },
  spin: { duration: 0.3, ease: ease.out },
  handoffOut: { duration: 0.22, ease: ease.soft },
  handoffIn: { duration: 0.26, ease: ease.arrive },
  dismiss: { duration: 0.2, ease: ease.away },
  shake: { duration: 0.4, ease: ease.inOut },
  drawerOut: { duration: 0.16, ease: ease.in },
  drawer: { duration: 0.4, ease: ease.drawer },
  sheet: { duration: 0.4, ease: ease.soft },
  collapse: { duration: 0.28, ease: ease.inOut },
  collapseLabel: { duration: 0.14, ease: ease.out },
  instant: { duration: 0 },
} as const satisfies Record<string, Transition>;

const scale = {
  press: 0.97,
  choice: 0.985,
  tooltip: 0.7,
  popover: 0.8,
  menu: 0.9,
  dialog: 0.8,
  icon: 0.5,
  toast: 0.96,
  fill: 0.7,
  action: 0.9,
} as const;

const blur = {
  icon: 'blur(2px)',
  tooltip: 'blur(6px)',
  disclosure: 'blur(2px)',
  surface: 'blur(4px)',
  panel: 'blur(5px)',
} as const;

const rotate = {
  icon: 90,
} as const;

const shift = {
  handoff: 6,
  navigation: 24,
  tabs: 12,
  step: 24,
  tooltip: 40,
  shake: 3,
} as const;

const stagger: { readonly stack: number } = {
  stack: 0.03,
};

const TIME_KEYS = [
  'duration',
  'visualDuration',
  'delay',
  'repeatDelay',
  'delayChildren',
];

function scaleTransition<T extends Transition | undefined>(
  value: T,
  tempo: number,
): T {
  if (!value || tempo === 1 || typeof value !== 'object') return value;
  const scaled: Record<string, unknown> = {};
  for (const [key, part] of Object.entries(value)) {
    if (typeof part === 'number' && TIME_KEYS.includes(key))
      scaled[key] = part * tempo;
    else if (typeof part === 'number' && key === 'stiffness')
      scaled[key] = part / (tempo * tempo);
    else if (typeof part === 'number' && key === 'damping')
      scaled[key] = part / tempo;
    else if (part && typeof part === 'object' && !Array.isArray(part))
      scaled[key] = scaleTransition(part as Transition, tempo);
    else scaled[key] = part;
  }
  return scaled as T;
}

function createMotionTokens(tempo = 1) {
  const pace = <T extends Record<string, Transition>>(set: T): T =>
    tempo === 1
      ? set
      : (Object.fromEntries(
          Object.entries(set).map(([role, value]) => [
            role,
            scaleTransition(value, tempo),
          ]),
        ) as T);

  return {
    tempo,
    ease,
    scale,
    blur,
    rotate,
    shift,
    stagger:
      tempo === 1
        ? stagger
        : (Object.fromEntries(
            Object.entries(stagger).map(([role, delay]) => [
              role,
              delay * tempo,
            ]),
          ) as typeof stagger),
    spring: pace(spring),
    transition: pace(transition),
  } as const;
}

type MotionTokens = ReturnType<typeof createMotionTokens>;
type CheckAnimation = 'draw' | 'pop';
type ReducedMotion = 'user' | 'never' | 'always';

const motionTokens: MotionTokens = createMotionTokens();

const MotionTokensKey: InjectionKey<Ref<MotionTokens>> = Symbol(
  'AnimateUIMotionTokens',
);
const CheckAnimationKey: InjectionKey<Ref<CheckAnimation>> = Symbol(
  'AnimateUICheckAnimation',
);
const ReducedMotionKey: InjectionKey<Ref<ReducedMotion>> = Symbol(
  'AnimateUIReducedMotion',
);

function useMotionTokens(): Ref<MotionTokens> {
  return inject(MotionTokensKey, ref(motionTokens) as Ref<MotionTokens>);
}

/** Scales a transition by the provider's `tempo`. */
function useTempoTransition<T extends Transition | undefined>(
  value: () => T,
): ComputedRef<T> {
  const tokens = useMotionTokens();
  return computed(() => scaleTransition(value(), tokens.value.tempo));
}

function useCheckAnimation(own?: () => CheckAnimation | undefined) {
  const inherited = inject(CheckAnimationKey, ref<CheckAnimation>('draw'));
  return computed(() => own?.() ?? inherited.value);
}

function useReducedMotionSetting(): ComputedRef<ReducedMotion> {
  const own = inject(ReducedMotionKey, ref<ReducedMotion>('user'));
  const config = useMotionConfig();
  return computed(() =>
    config.value.reducedMotion === 'always' ? 'always' : own.value,
  );
}

type CssTiming = { duration: number; easing: string };

const CSS_EASINGS: Record<string, string> = {
  linear: 'linear',
  easeIn: 'cubic-bezier(0.42, 0, 1, 1)',
  easeOut: 'cubic-bezier(0, 0, 0.58, 1)',
  easeInOut: 'cubic-bezier(0.42, 0, 0.58, 1)',
  circIn: 'cubic-bezier(0, 0.65, 0.55, 1)',
  circOut: 'cubic-bezier(0.55, 0, 1, 0.45)',
  backIn: 'cubic-bezier(0.31, 0.01, 0.66, -0.59)',
  backOut: 'cubic-bezier(0.33, 1.53, 0.69, 0.99)',
};

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

function toCssEase(curve: unknown): string {
  if (
    Array.isArray(curve) &&
    curve.length === 4 &&
    curve.every(Number.isFinite)
  )
    return `cubic-bezier(${curve.join(', ')})`;
  if (typeof curve === 'string') return CSS_EASINGS[curve] ?? 'ease';
  return CSS_EASINGS.easeInOut!;
}

function toCssTiming(motionTransition: Transition): CssTiming {
  const options = motionTransition as Record<string, unknown>;
  const isSpring =
    options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

  if (isSpring) {
    const springOptions =
      typeof options.duration === 'number'
        ? { ...options, duration: options.duration * 1000 }
        : options;
    const { duration, ease: curve } = createGeneratorEasing(
      springOptions,
      100,
      springGenerator,
    );
    const ms = Math.round(duration * 1000);
    return { duration: ms, easing: generateLinearEasing(curve, ms) };
  }

  const seconds = typeof options.duration === 'number' ? options.duration : 0.3;
  return {
    duration: Math.round(seconds * 1000),
    easing: toCssEase(options.ease),
  };
}

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

// Once the app has mounted (hydrated), later components read the setting at once.
const appMounted = () =>
  Boolean(
    (
      getCurrentInstance()?.appContext.app as
        { _container?: unknown } | undefined
    )?._container,
  );

/** False on the server and while hydrating, then follows the OS setting. */
function useShouldReduceMotion(): ComputedRef<boolean> {
  const setting = useReducedMotionSetting();
  const prefersReduced = ref(
    appMounted() && window.matchMedia(REDUCED_MOTION_QUERY).matches,
  );
  let query: MediaQueryList | undefined;
  const update = () => {
    prefersReduced.value = query?.matches ?? false;
  };
  onMounted(() => {
    query = window.matchMedia(REDUCED_MOTION_QUERY);
    update();
    query.addEventListener('change', update);
  });
  onBeforeUnmount(() => query?.removeEventListener('change', update));
  return computed(() => {
    if (setting.value === 'never') return false;
    return setting.value === 'always' || prefersReduced.value;
  });
}

const RemountOnReduce = defineComponent({
  name: 'RemountOnReduce',
  setup(_, { slots }) {
    const reduce = useShouldReduceMotion();
    return () =>
      h(Fragment, { key: reduce.value ? 'reduce' : 'full' }, slots.default?.());
  },
});

const ReducedMotionConfig = defineComponent({
  name: 'ReducedMotionConfig',
  props: { remount: Boolean },
  setup(props, { slots }) {
    const reducedMotion = useReducedMotionSetting();
    return () =>
      h(MotionConfig, { reducedMotion: reducedMotion.value }, () =>
        props.remount ? h(RemountOnReduce, null, slots) : slots.default?.(),
      );
  },
});

export {
  createMotionTokens,
  motionTokens,
  MotionTokensKey,
  CheckAnimationKey,
  ReducedMotionKey,
  useMotionTokens,
  useCheckAnimation,
  ease,
  spring,
  transition,
  scale,
  blur,
  rotate,
  shift,
  stagger,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useReducedMotionSetting,
  scaleTransition,
  toCssTiming,
  useTempoTransition,
  type CssTiming,
  type MotionTokens,
  type CheckAnimation,
